    let inputCard: BankCard = l({
      logic: () => validatedCard,
      description: "validatedCard",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(validatedCard) === false,
        description: "validatedCard.oclIsUndefined()=false",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

